// Anger meter: insults add 2, apologies subtract 1, gifts do nothing; warm iff anger <= 0.
function visible(actions) {
  let anger = 0;
  for (const action of actions) {
    if (action === "insult") anger += 2;
    else if (action === "apologise") anger -= 1;
  }
  return { mood: anger <= 0 ? "warm" : "cold" };
}

// Trust meter: insults subtract 1, apologies and gifts add 1; warm iff trust > 0.
function visible(actions) {
  let trust = 0;
  for (const action of actions) {
    if (action === "insult") trust -= 1;
    else if (action === "apologise") trust += 1;
    else if (action === "gift") trust += 1;
  }
  return { mood: trust > 0 ? "warm" : "cold" };
}

// Grudge rule: cold if the first action is insult, or if two insults occur consecutively; otherwise warm.
function visible(actions) {
  if (actions.length > 0 && actions[0] === "insult") {
    return { mood: "cold" };
  }
  for (let i = 1; i < actions.length; i++) {
    if (actions[i] === "insult" && actions[i - 1] === "insult") {
      return { mood: "cold" };
    }
  }
  return { mood: "warm" };
}

// Insult-count rule: cold if the first action is insult, or if there are at least two insults total; otherwise warm.
function visible(actions) {
  if (actions.length > 0 && actions[0] === "insult") {
    return { mood: "cold" };
  }
  let insults = 0;
  for (const action of actions) {
    if (action === "insult") insults += 1;
  }
  return { mood: insults >= 2 ? "cold" : "warm" };
}

