// Warm when apologies strictly outnumber insults; gifts are ignored.
function visible(actions) {
  let insults = 0;
  let apologies = 0;
  for (const action of actions) {
    if (action === "insult") insults++;
    else if (action === "apologise") apologies++;
  }
  return { mood: apologies > insults ? "warm" : "cold" };
}

// Score = 2*(apologies - insults) + gifts; warm when score is at least 1.
function visible(actions) {
  let score = 0;
  for (const action of actions) {
    if (action === "insult") score -= 2;
    else if (action === "apologise") score += 2;
    else if (action === "gift") score += 1;
  }
  return { mood: score >= 1 ? "warm" : "cold" };
}

// Score = 4*apologies - 3*insults; warm when score is at least 3. Gifts are ignored.
function visible(actions) {
  let score = 0;
  for (const action of actions) {
    if (action === "insult") score -= 3;
    else if (action === "apologise") score += 4;
  }
  return { mood: score >= 3 ? "warm" : "cold" };
}

// Warm if apologies outnumber insults, or if the last action was an apology and apologies+gifts outnumber insults.
function visible(actions) {
  let insults = 0;
  let apologies = 0;
  let gifts = 0;
  for (const action of actions) {
    if (action === "insult") insults++;
    else if (action === "apologise") apologies++;
    else if (action === "gift") gifts++;
  }
  const last = actions.length ? actions[actions.length - 1] : "";
  const warm =
    apologies > insults ||
    (last === "apologise" && apologies + gifts > insults);
  return { mood: warm ? "warm" : "cold" };
}

