// Warm iff -2*insults + apologies + gifts is positive and the last action was not an insult.
function visible(actions) {
  let score = 0;
  for (const action of actions) {
    if (action === "insult") score -= 2;
    else if (action === "apologise") score += 1;
    else if (action === "gift") score += 1;
  }
  const last = actions[actions.length - 1];
  return { mood: score > 0 && last !== "insult" ? "warm" : "cold" };
}

// Warm iff trust is positive and no insult remains unapologised; gifts add trust but do not forgive insults.
function visible(actions) {
  let trust = 0;
  let unforgiven = false;
  for (const action of actions) {
    if (action === "insult") {
      trust -= 1;
      unforgiven = true;
    } else if (action === "apologise") {
      trust += 1;
      unforgiven = false;
    } else if (action === "gift") {
      trust += 1;
    }
  }
  return { mood: trust > 0 && !unforgiven ? "warm" : "cold" };
}

// Warm iff -3*insults + 2*apologies + gifts is positive, and either there were fewer than 2 insults or the last action was an apology.
function visible(actions) {
  let score = 0;
  let insults = 0;
