    if (action === "insult") {
      score -= 3;
      insults += 1;
    } else if (action === "apologise") {
      score += 2;
    } else if (action === "gift") {
      score += 1;
    }
  }
  const last = actions[actions.length - 1];
  return { mood: score > 0 && (insults < 2 || last === "apologise") ? "warm" : "cold" };
}

